import { Effect, Schema } from "effect"

export class InvalidReservationQuantity extends Schema.TaggedErrorClass<InvalidReservationQuantity>()(
  "InvalidReservationQuantity",
  {
    quantity: Schema.Number
  }
) {}

export class UnknownStockItem extends Schema.TaggedErrorClass<UnknownStockItem>()(
  "UnknownStockItem",
  {
    sku: Schema.String
  }
) {}

export class InsufficientStock extends Schema.TaggedErrorClass<InsufficientStock>()(
  "InsufficientStock",
  {
    sku: Schema.String,
    requested: Schema.Number,
    available: Schema.Number
  }
) {}

export const reserveStock = (
  inventory: ReadonlyMap<string, number>,
  sku: string,
  quantity: number
) =>
  Effect.gen(function*() {
    if (!Number.isSafeInteger(quantity) || quantity <= 0) {
      return yield* Effect.fail(new InvalidReservationQuantity({ quantity }))
    }
    const available = inventory.get(sku)
    if (available === undefined) {
      return yield* Effect.fail(new UnknownStockItem({ sku }))
    }
    if (quantity > available) {
      return yield* Effect.fail(new InsufficientStock({
        sku,
        requested: quantity,
        available
      }))
    }
    const updated = new Map(inventory)
    updated.set(sku, available - quantity)
    return updated
  })
